import{_t as e,it as t,n,rt as r}from"./chunks/framework.XJu5filh.js";import"./chunks/assets.DWopfgZq.js";var i=JSON.parse(`{"title":"设置","description":"","frontmatter":{},"headers":[],"relativePath":"feature/setting.md","filePath":"feature/setting.md","lastUpdated":1792829874000}`),a={name:`feature/setting.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to “设置”">​</a></h1><p>扩展与桌面端从底部头像菜单打开“设置”。当前设置按“首页展示”“通知与声音”“掉落提醒”“配置与角色”分组，桌面端还提供“游戏代理”和“用户脚本”。一般设置修改后即时保存，代理和脚本按各自按钮保存。</p><p>本页截图来自旧版，分组名称和控件位置以正文说明为准。移动端使用独立设置页，差异见<a href="#移动端设置">移动端设置</a>。</p><h2 id="主页设置" tabindex="-1">主页设置 <a class="header-anchor" href="#主页设置" aria-label="Permalink to “主页设置”">​</a></h2><p><img src="/tarou-docs/assets/img/setting-img1.gif" alt="alt text" width="304" height="244"></p><p>在“首页展示”中使用开关控制模块显隐，拖动每项的手柄改变显示顺序；列表从上到下对应实际首页顺序。</p><h2 id="弹窗通知" tabindex="-1">弹窗通知 <a class="header-anchor" href="#弹窗通知" aria-label="Permalink to “弹窗通知”">​</a></h2><p><img src="/tarou-docs/assets/img/setting-img2.png" alt="alt text" width="293" height="330"></p><p>“通知与声音”提供战斗结束、队伍全灭、沙盒宝箱、Hell 出现、道具数量达到目标、探险完成、贡献达到目标和动作触发八项提醒。底部调节提示音量，也可以直接静音；调整完成后会试听。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>扩展使用浏览器扩展通知，需要操作系统允许对应浏览器发送通知；桌面端使用系统通知，需要操作系统允许 Tarou 发送通知。系统勿扰模式等设置也可能影响展示。</p></div><h2 id="掉落提醒" tabindex="-1">掉落提醒 <a class="header-anchor" href="#掉落提醒" aria-label="Permalink to “掉落提醒”">​</a></h2><p><img src="/tarou-docs/assets/img/setting-img3.png" alt="alt text" width="304" height="326"></p><p>开启“监控道具掉落”后，在标记的物品掉落时触发提醒。鼠标悬浮在物品图片上会显示删除按钮，点击即可移除该物品。</p><p><img src="/tarou-docs/assets/img/setting-img4.png" alt="alt text" width="467" height="293"></p><p>扩展与桌面端可在游戏页面的道具图片上右键，选择“加入掉落监控”；只支持能识别为道具的图片，不能在任意网页或任意图片上添加。</p><h2 id="自动上传队伍配置" tabindex="-1">自动上传队伍配置 <a class="header-anchor" href="#自动上传队伍配置" aria-label="Permalink to “自动上传队伍配置”">​</a></h2><p>“配置与角色”中的“自动上传队伍配置”控制战斗结算时的配置上传，默认开启。需要先登录太郎账号并读取对应队伍信息，详见<a href="./history#上传">战斗记录</a>。它与会员的<a href="./info#配置上传同步">配置自动同步</a>是两个功能。</p><h2 id="未拥有角色" tabindex="-1">未拥有角色 <a class="header-anchor" href="#未拥有角色" aria-label="Permalink to “未拥有角色”">​</a></h2><p><img src="/tarou-docs/assets/img/setting-img5.png" alt="alt text" width="296" height="135"></p><p>“配置与角色”中的“未持有角色”用于<a href="./build">配置查询</a>时排除包含这些角色的配置。鼠标悬浮在角色图片上会显示删除按钮，点击即可移除筛选。添加角色方式参考<a href="./build">配置查询</a>中的说明。</p><h2 id="游戏代理" tabindex="-1">游戏代理 <a class="header-anchor" href="#游戏代理" aria-label="Permalink to “游戏代理”">​</a></h2><p>仅桌面端提供，默认“跟随系统”，也可以选择“直连”“手动代理”或“PAC”。手动代理支持 HTTP、HTTPS、SOCKS4、SOCKS5，地址省略协议时按 HTTP 处理，不支持用户名和密码认证。绕过规则可选，多个规则用分号分隔；PAC 需填写 HTTP/HTTPS 地址。</p><p>点击“保存并应用”后生效，必要时手动刷新游戏。该设置只影响游戏页面与登录弹窗，不会改变太郎云端接口或更新下载使用的网络，也不会自动验证代理是否连通。</p><h2 id="本地缓存" tabindex="-1">本地缓存 <a class="header-anchor" href="#本地缓存" aria-label="Permalink to “本地缓存”">​</a></h2><p>桌面端和移动端在设置中直接展示“本地缓存”，桌面端位于“游戏代理”上方。桌面和 Android 默认缓存官方图片、字体与音频，容量上限均为 <strong>5 GB</strong>，用到多少占多少，达到上限后自动淘汰较久未使用的内容。缓存遵守资源的有效期，不会永久固定旧图片；游戏脚本和动态接口继续使用原有方式加载。音频与其他资源共用 5 GB，只保存完整下载的文件；播放和拖动进度可以读取完整缓存中的对应片段，未命中时正常走网络，不额外下载整首音频。</p><p>页面显示独立缓存大小、数量，以及本次启动的命中、重新验证、未命中和失败次数。命中率只计算新增缓存层处理的请求，系统提前命中的资源不在其中；本地读取量不代表准确节省的流量，系统缓存还可能额外占用空间。可以随时关闭缓存，已有文件会保留。</p><p>iOS 继续使用系统缓存，无法读取准确大小、数量或命中率，页面会显示“系统未提供”，也不能设置 5 GB 上限。仍可点击“清理资源缓存”，清除系统保存的资源缓存。</p><p>清理资源缓存不会退出游戏登录，也不会删除书签、配置、战斗记录或用户脚本，不主动刷新游戏；当前页面已显示的资源可能仍在内存中。该入口与“清理登录缓存”作用不同。缓存主要改善重复资源加载，不能解决动画低帧率，无需安装证书或申请额外权限。</p><h2 id="用户脚本" tabindex="-1">用户脚本 <a class="header-anchor" href="#用户脚本" aria-label="Permalink to “用户脚本”">​</a></h2><p>桌面端和移动端在设置中提供“用户脚本”。点击“添加脚本”，可输入脚本地址后“下载查看”，或切换到“粘贴代码”，确认内容后“添加并启用”。列表支持单独启停、编辑和删除，地址来源的脚本可以手动更新，不会后台自动更新。</p><p>脚本增删、更新或启停后，需要刷新游戏才能完整生效。该功能只支持部分用户脚本能力，并非完整的 Tampermonkey 环境；不支持的声明会在保存时提示错误。</p><p>支持 <code>unsafeWindow</code>、<code>GM_xmlhttpRequest</code>、返回 Promise 的 <code>GM.xmlHttpRequest</code>、插入样式的 <code>GM_addStyle</code>，以及脚本声明的四种执行时机；<code>@exclude</code> 与 <code>@exclude-match</code> 支持匹配规则格式的排除项。可导入片假名终结者 <code>2022.02.18</code> 原脚本，为游戏页面中的片假名词语添加英文标注，翻译请求需要能够访问 Google 翻译服务。</p><p>跨域请求需按脚本的 <code>@connect</code> 声明授权。脚本仅在游戏页面执行，不在登录平台页面运行。移动端脚本下载和跨域资源仅支持 HTTPS，重定向至 HTTP 也会失败；Android 系统 WebView 缺少必要能力时，需要更新 Android System WebView 后重试。</p><p>游戏代理与用户脚本仅保存在当前设备，不参与云端同步。</p><h2 id="移动端设置" tabindex="-1">移动端设置 <a class="header-anchor" href="#移动端设置" aria-label="Permalink to “移动端设置”">​</a></h2><p>移动端从菜单进入“设置”，提供通知提醒、掉落提醒开关与监控列表，用户脚本、<a href="#本地缓存">本地缓存</a>，以及“清理登录缓存”。通知以应用内顶部提示展示，不发送系统通知，也不播放桌面与扩展的通知音效。</p><p>移动端提供与桌面端共用的<a href="#用户脚本">用户脚本管理</a>，脚本在强退重开后保留，登出太郎和清理游戏登录缓存也不会删除脚本。</p><p>移动端没有首页排序、通知音量、动作触发开关、自动上传开关、未持有角色管理、游戏代理或右键添加掉落监控入口。当前设备保存的提醒开关和监控列表仍会用于对应功能。</p><p>“清理登录缓存”经确认后清除游戏网页的 Cookie 和站点数据，用于重新登录游戏；与太郎账号的<a href="./info#登出">登出</a>操作不同。</p><h2 id="新版本提示" tabindex="-1">新版本提示 <a class="header-anchor" href="#新版本提示" aria-label="Permalink to “新版本提示”">​</a></h2><p>新版本检测没有提醒开关。有新版本时，桌面与扩展在菜单头像上方、Android 在菜单顶部显示蓝色下载按钮。安装和更新步骤见<a href="./../begin/start">快速开始</a>。</p>`,41)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};